head.script:
/**/
  (function(){try{
    var k='ahub-theme',s=localStorage.getItem(k);
    var d = s ? (s==='dark') : (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
    var r=document.documentElement;
    r.setAttribute('data-theme', d?'dark':'light');
    if(d) r.setAttribute('mode','dark');
  }catch(e){}})();
  /**/

head.b:skin:
/*
 ═══════════════════════════════════════════════════════════════════
  Hub Template  —  design system & skin
  كل سطر في هذا الملف مكتوب من الصفر لهذا القالب. لا يحتوي أي كود
  من قوالب أخرى. مبني على مبادئ هندسية بشبكة 4px.
 ═══════════════════════════════════════════════════════════════════
*/
<Group description="🎨 الألوان الأساسية" selector="body">
  <Variable name="keycolor" description="اللون الرئيسي (روابط وأزرار)" type="color" default="#4f46e5" value="#4f46e5"/>
  <Variable name="bodybgcolor" description="خلفية الموقع" type="color" default="#FBF3E0" value="#FBF3E0"/>
  <Variable name="headerbgcolor" description="خلفية الهيدر" type="color" default="#FFFDF6" value="#FFFDF6"/>
  <Variable name="textcolor" description="لون النص" type="color" default="#15161C" value="#15161C"/>
</Group>
<Group description="📐 التخطيط" selector="body">
  <Variable name="contentwidth" description="عرض المحتوى" type="length" default="1160px" min="960px" max="1600px" value="1160px"/>
  <Variable name="sidebarwidth" description="عرض القائمة الجانبية" type="length" default="330px" min="260px" max="420px" value="330px"/>
</Group>
<Group description="🌙 الوضع الليلي" selector="body">
  <Variable name="darkbg" description="خلفية الوضع الليلي" type="color" default="#14161F" value="#14161F"/>
  <Variable name="darkcard" description="بطاقة الوضع الليلي" type="color" default="#1B1E2B" value="#1B1E2B"/>
  <Variable name="darktext" description="نص الوضع الليلي" type="color" default="#E9EBF3" value="#E9EBF3"/>
</Group>
*/
/* ═══════════ ① الأساسيات ═══════════ */
:root{
  --brand:$(keycolor);
  --bg:$(bodybgcolor);
  --hdr:$(headerbgcolor);
  --ink:$(textcolor);
  --shell:$(contentwidth);
  --side:$(sidebarwidth);
  --dark-bg:$(darkbg);
  --dark-card:$(darkcard);
  --dark-ink:$(darktext);
  --brand-ink:#fff;

  --u1:4px; --u2:8px; --u3:12px; --u4:16px; --u5:20px; --u6:24px; --u8:32px; --u10:40px; --u12:48px;
  --r1:10px; --r2:14px; --r3:18px;
  --ctl:42px; --ctl-ico:19px;

  --card:#FFFDF6;
  --muted:#5B5C66;
  --line:rgba(21,22,28,.10);
  --line2:rgba(21,22,28,.16);
  --soft:rgba(21,22,28,.045);
  --glass:rgba(255,252,244,.82);
  --glass-solid:#FDF8EC;
  --shadow:0 6px 24px rgba(24,18,4,.07);
  --shadow-lg:0 18px 48px rgba(24,18,4,.12);
  --th:var(--brand);
  --grad:linear-gradient(135deg,$(keycolor),#06b6d4);
  --tex:url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27160%27%20height%3D%27160%27%3E%3Cfilter%20id%3D%27n%27%3E%3CfeTurbulence%20type%3D%27fractalNoise%27%20baseFrequency%3D%270.85%27%20numOctaves%3D%272%27%20stitchTiles%3D%27stitch%27%2F%3E%3CfeColorMatrix%20type%3D%27matrix%27%20values%3D%270%200%200%200%200.38%200%200%200%200%200.30%200%200%200%200%200.12%200%200%200%200.055%200%27%2F%3E%3C%2Ffilter%3E%3Crect%20width%3D%27160%27%20height%3D%27160%27%20filter%3D%27url(%23n)%27%2F%3E%3C%2Fsvg%3E");
}
html[data-theme="dark"]{
  --bg:var(--dark-bg); --card:var(--dark-card); --hdr:#181B26;
  --ink:var(--dark-ink); --muted:#A7ABC0;
  --line:rgba(255,255,255,.12); --line2:rgba(255,255,255,.20); --soft:rgba(255,255,255,.06);
  --glass:rgba(20,22,31,.80); --glass-solid:#161923;
  --shadow:0 6px 24px rgba(0,0,0,.30); --shadow-lg:0 18px 48px rgba(0,0,0,.45);
  --th:#262B4A; color-scheme:dark;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;background:var(--bg)}
body{
  margin:0;background:var(--bg);background-image:var(--tex);background-repeat:repeat;
  color:var(--ink);font-family:"Segoe UI",system-ui,-apple-system,"Helvetica Neue",Roboto,Arial,sans-serif;
  font-size:16.5px;line-height:1.8;overflow-x:hidden;
}
img{max-width:100%;height:auto;border:0}
a{color:var(--brand);text-decoration:none}
a:hover{text-decoration:underline;text-underline-offset:3px}
h1,h2,h3,h4{line-height:1.35;margin:0 0 var(--u3);font-weight:800;letter-spacing:-.2px}
p{margin:0 0 var(--u4)}
ul,ol{padding-inline-start:22px}
:focus-visible{outline:2px solid var(--brand);outline-offset:2px;border-radius:6px}
::selection{background:var(--brand);color:#fff}
.shell{max-width:var(--shell);margin:0 auto;padding:0 var(--u4)}
.sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip-link{position:absolute;inset-inline-start:-9999px;top:0;background:var(--brand);color:#fff;padding:10px 16px;z-index:60;border-radius:0 0 var(--r1) 0}
.skip-link:focus{inset-inline-start:0}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.001ms!important;transition-duration:.001ms!important}
}

/* ═══════════ ② الهيدر ═══════════ */
.site-header{position:sticky;top:0;z-index:40;background:var(--glass);border-bottom:1px solid var(--line);backdrop-filter:saturate(180%) blur(14px);-webkit-backdrop-filter:saturate(180%) blur(14px);transition:box-shadow .25s}
@supports not ((backdrop-filter:blur(4px)) or (-webkit-backdrop-filter:blur(4px))){.site-header{background:var(--glass-solid)}}
.site-header.is-scrolled{box-shadow:var(--shadow)}
.hdr-top{display:none;border-bottom:1px solid var(--line);font-size:14px}
.hdr-top .shell{display:flex;align-items:center;gap:var(--u4);min-height:38px}
.hdr-top nav ul{display:flex;gap:var(--u2);list-style:none;margin:0;padding:0;flex-wrap:wrap}
.hdr-top nav a{padding:var(--u1) var(--u2);border-radius:8px;color:var(--muted);font-weight:600}
.hdr-top nav a:hover{background:var(--soft);text-decoration:none;color:var(--ink)}
.hdr-main .shell{display:flex;align-items:center;gap:var(--u3);min-height:72px}
.brand{display:flex;align-items:center;gap:var(--u3);min-width:0}
.brand .title{font-size:22px;font-weight:900;margin:0;letter-spacing:-.4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.brand .title a{color:var(--ink)}
.brand .title a:hover{text-decoration:none;color:var(--brand)}
.brand img{max-height:46px;width:auto}
.brand .description{display:none;margin:0;font-size:13.5px;color:var(--muted)}
.main-nav{margin-inline-start:auto}
.main-nav ul{display:flex;align-items:center;gap:var(--u1);list-style:none;margin:0;padding:0}
.main-nav a{display:inline-flex;align-items:center;height:var(--ctl);padding:0 var(--u3);border-radius:var(--r1);font-weight:600;color:var(--ink);font-size:15.5px}
.main-nav a:hover{background:var(--soft);text-decoration:none;color:var(--brand)}
.hdr-actions{display:flex;align-items:center;gap:var(--u2);flex-shrink:0}
.icon-btn{display:inline-flex;align-items:center;justify-content:center;width:var(--ctl);height:var(--ctl);border:1px solid var(--line);border-radius:var(--r2);background:var(--soft);color:var(--ink);cursor:pointer;padding:0;transition:background .18s,border-color .18s,color .18s}
.icon-btn svg{width:var(--ctl-ico);height:var(--ctl-ico);display:block}
.icon-btn:hover{background:var(--brand);border-color:var(--brand);color:#fff}
.icon-btn:hover svg{stroke:#fff}
.nav-toggle{display:none}
/* صندوق البحث */
.hdr-search{position:relative;display:flex;align-items:center}
.hdr-search input[type=search]{width:0;opacity:0;padding:0;border:0;height:var(--ctl);border-radius:var(--r2);background:var(--card);color:var(--ink);transition:width .25s,opacity .2s,padding .25s;font:inherit;font-size:15px}
.hdr-search.open input[type=search]{width:min(46vw,300px);opacity:1;padding:0 var(--u3);border:1px solid var(--line)}
.hdr-search.open input[type=search]:focus{outline:2px solid var(--brand);outline-offset:1px}
/* الشريط السفلي للهاتف */
.mobile-bar{display:none}
@media (hover:none){.icon-btn:hover{background:var(--soft);border-color:var(--line);color:var(--ink)}.icon-btn:hover svg{stroke:currentColor}}
@media (max-width:980px){
  .main-nav{position:fixed;inset:0 0 0 auto;inset-inline-end:0;width:min(84vw,340px);background:var(--card);border-inline-start:1px solid var(--line);box-shadow:var(--shadow-lg);transform:translateX(105%);transition:transform .28s ease;z-index:50;padding:var(--u5) var(--u4) var(--u8);overflow-y:auto;margin:0;height:100dvh}
  html[dir=rtl] .main-nav{transform:translateX(-105%)}
  .main-nav.is-open{transform:translateX(0)!important}
  .main-nav ul{flex-direction:column;align-items:stretch;gap:var(--u1)}
  .main-nav a{height:48px;border-radius:var(--r2);font-size:16.5px}
  .nav-toggle{display:inline-flex}
  .nav-close{display:inline-flex;margin-inline-start:auto;margin-bottom:var(--u3)}
  .nav-scrim{position:fixed;inset:0;background:rgba(16,14,8,.5);opacity:0;visibility:hidden;transition:opacity .25s;z-index:45;border:0;padding:0}
  .nav-scrim.is-open{opacity:1;visibility:visible}
  .hdr-main .shell{min-height:64px}
  .brand .title{font-size:19.5px}
}
@media (min-width:981px){.nav-close{display:none}}

/* ═══════════ ③ التخطيط العام ═══════════ */
.layout{display:grid;grid-template-columns:minmax(0,1fr) var(--side);gap:var(--u8);align-items:start;padding:var(--u8) 0 var(--u10)}
.layout.no-side{grid-template-columns:minmax(0,1fr);max-width:820px;margin:0 auto}
@media (max-width:980px){.layout{grid-template-columns:minmax(0,1fr);gap:var(--u6);padding:var(--u5) 0 var(--u8)}}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r3);box-shadow:var(--shadow)}
.section-title{display:flex;align-items:center;gap:var(--u2);font-size:20px;margin:0 0 var(--u4)}
.section-title::before{content:"";width:4px;height:20px;border-radius:4px;background:var(--brand)}
.breadcrumbs{font-size:14px;color:var(--muted);margin:var(--u5) 0 0;display:flex;flex-wrap:wrap;gap:var(--u2)}
.breadcrumbs a{color:var(--muted)}
.breadcrumbs span.sep{opacity:.5}

/* ═══════════ ④ شبكة المقالات (الرئيسية) ═══════════ */
.index-head{padding:var(--u6) 0 0}
.index-title{font-size:29px;margin:0 0 var(--u2)}
.index-sub{color:var(--muted);margin:0 0 var(--u5);font-size:16px}
.post-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--u5);margin-top:var(--u6)}
@media (max-width:700px){.post-grid{grid-template-columns:minmax(0,1fr);gap:var(--u4)}}
.pcard{display:flex;flex-direction:column;overflow:hidden;transition:transform .2s,box-shadow .2s}
@media (hover:hover){.pcard:hover{transform:translateY(-3px);box-shadow:var(--shadow-lg)}}
.pcard .thumb{display:block;aspect-ratio:16/9;background:var(--soft);overflow:hidden}
.pcard .thumb img{width:100%;height:100%;object-fit:cover;display:block}
.pcard .body{padding:var(--u5);display:flex;flex-direction:column;gap:var(--u2);flex:1}
.pcard .cat{align-self:flex-start;font-size:12.5px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--brand);background:var(--soft);border:1px solid var(--line);padding:3px 10px;border-radius:999px}
.pcard h2{font-size:20.5px;margin:0}
.pcard h2 a{color:var(--ink)}
.pcard h2 a:hover{color:var(--brand);text-decoration:none}
.pcard p{margin:0;color:var(--muted);font-size:15.5px;line-height:1.7}
.pcard .meta{margin-top:auto;padding-top:var(--u2);font-size:13.5px;color:var(--muted);display:flex;gap:var(--u2);align-items:center;flex-wrap:wrap}
.pcard .meta svg{width:15px;height:15px;opacity:.7}
.pager{display:flex;justify-content:space-between;gap:var(--u3);margin:var(--u8) 0 0;flex-wrap:wrap}
.pager a{display:inline-flex;align-items:center;gap:var(--u2);height:46px;padding:0 var(--u5);border:1px solid var(--line);border-radius:var(--r2);background:var(--card);font-weight:700;color:var(--ink)}
.pager a:hover{background:var(--brand);border-color:var(--brand);color:#fff;text-decoration:none}
.pager .spacer{flex:1}

/* ═══════════ ⑤ صفحة المقال ═══════════ */
.post{background:var(--card);border:1px solid var(--line);border-radius:var(--r3);box-shadow:var(--shadow);padding:var(--u6) var(--u6) var(--u5)}
@media (max-width:700px){.post{padding:var(--u5) var(--u4);border-radius:var(--r2)}}
.post-title{font-size:31px;line-height:1.3;margin:0 0 var(--u4)}
@media (max-width:700px){.post-title{font-size:25px}}
.byline{display:flex;align-items:center;gap:var(--u3);background:var(--soft);border:1px solid var(--line);border-radius:var(--r2);padding:var(--u3) var(--u4);margin:0 0 var(--u5);font-size:14.5px;color:var(--muted)}
.byline img{width:36px;height:36px;border-radius:50%;object-fit:cover}
.byline b{color:var(--ink)}
.byline .read{display:block;font-size:13.5px}
.post-body{font-size:17.5px;line-height:1.85}
.post-body h2{font-size:24px;margin:var(--u8) 0 var(--u4);scroll-margin-top:96px}
.post-body h3{font-size:20px;margin:var(--u6) 0 var(--u2);scroll-margin-top:96px}
.post-body p{margin:0 0 var(--u4)}
.post-body a{border-bottom:1px solid color-mix(in srgb,var(--brand) 45%,transparent)}
.post-body a:hover{text-decoration:none;border-bottom-color:var(--brand)}
.post-body ul,.post-body ol{margin:0 0 var(--u4);display:grid;gap:var(--u2)}
.post-body li{line-height:1.75}
.post-body img{border-radius:var(--r2);box-shadow:var(--shadow);display:block;margin:var(--u5) auto}
.post-body figure{margin:var(--u5) 0}
.post-body figcaption{text-align:center;font-size:14px;color:var(--muted);margin-top:var(--u2)}
.post-body blockquote{margin:var(--u5) 0;padding:var(--u4) var(--u5);border-inline-start:4px solid var(--brand);background:var(--soft);border-radius:0 var(--r2) var(--r2) 0;font-size:17px;color:var(--ink)}
.post-body blockquote p:last-child{margin:0}
.post-body code{background:var(--soft);padding:2px 7px;border-radius:6px;font-size:15px;direction:ltr;display:inline-block}
.post-body pre{background:#14161F;color:#E9EBF3;padding:var(--u4);border-radius:var(--r2);overflow-x:auto;direction:ltr;text-align:start;font-size:14.5px;line-height:1.7}
.post-body pre code{background:none;padding:0;color:inherit;display:block}
.post-body hr{border:0;border-top:1px solid var(--line);margin:var(--u8) 0}
/* الجداول */
.post-body .tbl-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:var(--u5) 0;border:1px solid var(--line);border-radius:var(--r2)}
.post-body table{width:100%;border-collapse:collapse;font-size:15.5px;background:var(--card);margin:0}
.post-body table th{background:var(--th);color:#fff;text-align:start;font-weight:700;font-size:14.5px;padding:var(--u3) var(--u4)}
.post-body table td{padding:var(--u3) var(--u4);border-top:1px solid var(--line);vertical-align:top}
.post-body table tr:nth-child(even) td{background:var(--soft)}
/* الأسئلة المنسدلة */
.post-body details,.ahub-faq details{border:1px solid var(--line);border-radius:var(--r2);margin:var(--u3) 0;background:transparent;overflow:hidden}
.post-body summary,.ahub-faq summary{cursor:pointer;font-weight:700;padding:var(--u3) var(--u4);min-height:50px;display:flex;align-items:center;gap:var(--u2);background:var(--soft);list-style:none;color:var(--ink)}
.post-body summary::-webkit-details-marker{display:none}
.post-body summary::before,.ahub-faq summary::before{content:"+";font-weight:800;color:var(--brand);font-size:19px;line-height:1;width:18px;text-align:center}
.post-body details[open] summary::before{content:"–"}
.post-body details[open] summary{background:color-mix(in srgb,var(--brand) 10%,transparent)}
.post-body details > *:not(summary){padding:0 var(--u4);margin-top:var(--u3)}
.post-body details > *:not(summary):last-child{margin-bottom:var(--u3)}
/* بطاقة الإجابة السريعة + الفهرس + المصادر + CTA */
.ahub-key{position:relative;background:linear-gradient(180deg,color-mix(in srgb,var(--brand) 8%,var(--card)),var(--card));border:1px solid color-mix(in srgb,var(--brand) 32%,transparent);border-radius:var(--r3);padding:var(--u6) var(--u5) var(--u4);margin:var(--u2) 0 var(--u6)}
.ahub-key-label{position:absolute;top:-12px;inset-inline-start:var(--u4);background:var(--brand);color:#fff;font-size:11.5px;font-weight:800;letter-spacing:.12em;border-radius:999px;padding:var(--u1) var(--u3)}
.ahub-key p:last-child{margin:0}
.toc{border:1px solid var(--line);border-radius:var(--r2);background:var(--soft);margin:var(--u5) 0}
.toc-head{display:flex;align-items:center;justify-content:space-between;gap:var(--u3);cursor:pointer;font-weight:700;font-size:15.5px;padding:0 var(--u4);height:52px;width:100%;background:none;border:0;color:var(--ink);font-family:inherit;text-align:start}
.toc-head .hint{font-size:11.5px;text-transform:uppercase;letter-spacing:.04em;opacity:.75;border:1px solid var(--line);border-radius:999px;padding:3px 9px}
.toc ol{margin:0;padding:0 var(--u5) var(--u4);display:grid;gap:2px;font-size:15px}
.toc li{list-style:decimal inside;color:var(--muted)}
.toc li::marker{color:var(--brand);font-weight:700}
.toc a{color:var(--ink)}
.toc[hidden]{display:none}
.ahub-src{border:1px dashed var(--line2);border-radius:var(--r2);padding:var(--u4) var(--u4) var(--u2);list-style:none;margin:var(--u5) 0;display:grid;gap:var(--u2)}
.ahub-src li{font-size:15.5px}
.ahub-cta{background:var(--grad);color:#fff;border-radius:var(--r3);padding:var(--u6) var(--u5);margin:var(--u8) 0 var(--u3)}
.ahub-cta h3{color:#fff;margin:0 0 var(--u2);font-size:20px}
.ahub-cta p{margin:0 0 var(--u3)}
.ahub-cta a{color:#fff;font-weight:700;text-decoration:underline}
.ahub-tip{background:color-mix(in srgb,#f59e0b 10%,transparent);border:1px solid color-mix(in srgb,#f59e0b 36%,transparent);border-inline-start:4px solid #f59e0b;border-radius:var(--r2);padding:var(--u1) var(--u4);margin:var(--u5) 0}
/* أدوات المقال */
.post-tags{display:flex;flex-wrap:wrap;gap:var(--u2);margin:var(--u6) 0 0}
.post-tags a{font-size:13.5px;font-weight:700;padding:5px 12px;border-radius:999px;background:var(--soft);border:1px solid var(--line);color:var(--muted)}
.post-tags a:hover{background:var(--brand);border-color:var(--brand);color:#fff;text-decoration:none}
.share{display:flex;flex-wrap:wrap;gap:var(--u2);align-items:center;margin:var(--u5) 0 0;padding-top:var(--u5);border-top:1px solid var(--line)}
.share span.lbl{font-size:14px;color:var(--muted);font-weight:700}
.share a,.share button{display:inline-flex;align-items:center;justify-content:center;gap:6px;width:var(--ctl);height:var(--ctl);border:1px solid var(--line);border-radius:var(--r2);background:var(--card);color:var(--ink);cursor:pointer;padding:0}
.share a:hover,.share button:hover{background:var(--brand);border-color:var(--brand);color:#fff;text-decoration:none}
.share svg{width:17px;height:17px}
.share button.copied{background:#16a34a;border-color:#16a34a;color:#fff}
.post-updated{margin:var(--u5) 0 0;padding-top:var(--u4);border-top:1px solid var(--line);font-size:14px;color:var(--muted);font-style:italic}

/* ═══════════ ⑥ التعليقات ═══════════ */
.comments{margin:var(--u6) 0 0;padding-top:var(--u5);border-top:1px solid var(--line)}
.comments h3{font-size:20px;margin:0 0 var(--u4)}
.comment{background:var(--soft);border:1px solid var(--line);border-radius:var(--r2);padding:var(--u4);margin:0 0 var(--u3)}
.comment .c-head{display:flex;align-items:center;gap:var(--u2);font-size:14px;color:var(--muted);margin-bottom:var(--u2)}
.comment .c-head img{width:30px;height:30px;border-radius:50%}
.comment .c-head b{color:var(--ink)}
.comment-body{font-size:16px}
.comment-body p:last-child{margin:0}
.comment-form{margin-top:var(--u5)}
.comment-form iframe{width:100%;border:1px solid var(--line);border-radius:var(--r2);background:var(--card)}
.comment-msg{font-size:14.5px;color:var(--muted)}

/* ═══════════ ⑦ القائمة الجانبية ═══════════ */
.sidebar{display:grid;gap:var(--u5)}
@media (min-width:981px){.sidebar{position:sticky;top:88px}}
.widget{background:var(--card);border:1px solid var(--line);border-radius:var(--r3);padding:var(--u5);box-shadow:var(--shadow)}
.widget .title,h2.title{font-size:17.5px;margin:0 0 var(--u4);padding-bottom:var(--u3);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:var(--u2)}
.widget .title::before{content:"";width:4px;height:18px;border-radius:4px;background:var(--brand)}
.widget ul{list-style:none;margin:0;padding:0;display:grid;gap:var(--u2)}
.widget li a{color:var(--ink);font-weight:600}
.widget li a:hover{color:var(--brand)}
.widget .label-size{font-size:12.5px;color:var(--muted);opacity:.8}
.widget.Label ul{display:flex;flex-wrap:wrap;gap:var(--u2)}
.widget.Label li a{display:inline-block;font-size:14px;font-weight:700;padding:6px 12px;border-radius:999px;background:var(--soft);border:1px solid var(--line);color:var(--muted)}
.widget.Label li a:hover{background:var(--brand);border-color:var(--brand);color:#fff;text-decoration:none}
.widget.PopularPosts li{display:flex;gap:var(--u3);align-items:center}
.widget.PopularPosts .item-thumbnail{flex-shrink:0;width:76px;height:56px;overflow:hidden;border-radius:var(--r1);background:var(--soft)}
.widget.PopularPosts .item-thumbnail img{width:100%;height:100%;object-fit:cover}
.widget.PopularPosts .item-title{font-size:15px;line-height:1.55;margin:0}
.widget.Profile .profile-img{width:84px;height:84px;border-radius:50%;object-fit:cover;margin:0 0 var(--u3)}
.widget.Profile .profile-datablock{margin:0}
.widget.Profile .profile-textblock{font-size:15px;color:var(--muted)}
.widget.Profile .profile-link{font-weight:700;font-size:14px}
.widget .post-summary{font-size:14.5px;color:var(--muted);margin:0 0 var(--u3)}
.widget input,.widget textarea,.widget select{width:100%;padding:11px var(--u3);border:1px solid var(--line);border-radius:var(--r1);background:var(--bg);color:var(--ink);font:inherit;font-size:15px}
.widget input[type=submit],.widget button,.widget .contact-form-button-submit{width:auto;background:var(--brand);color:#fff;border:0;font-weight:700;cursor:pointer;padding:11px var(--u5);border-radius:var(--r1)}
.widget .contact-form-error-message-with-border,.widget .contact-form-success-message{font-size:14px}

/* ═══════════ ⑧ الفوتر ═══════════ */
.site-footer{margin-top:var(--u10);background:linear-gradient(180deg,color-mix(in srgb,var(--card) 92%,transparent),var(--bg));border-top:1px solid var(--line)}
.foot-cols{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--u5);padding:var(--u8) 0}
@media (max-width:860px){.foot-cols{grid-template-columns:minmax(0,1fr);gap:var(--u4);padding:var(--u6) 0}}
.foot-cols .widget{background:transparent;border:0;box-shadow:none;padding:0}
.foot-bottom{border-top:1px solid var(--line);padding:var(--u5) 0;display:flex;align-items:center;gap:var(--u4);flex-wrap:wrap;font-size:14px;color:var(--muted)}
.foot-bottom .shell{display:flex;align-items:center;gap:var(--u4);flex-wrap:wrap;width:100%}
.attribution{margin-inline-start:auto;font-size:13.5px;display:flex;gap:var(--u3);flex-wrap:wrap;align-items:center}
.attribution a{color:var(--muted)}
.foot-social{display:flex;gap:var(--u2)}
.foot-social a{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border:1px solid var(--line);border-radius:var(--r1);color:var(--muted);background:var(--soft)}
.foot-social a:hover{background:var(--brand);border-color:var(--brand);color:#fff}
.foot-social svg{width:18px;height:18px}

/* ═══════════ ⑨ عناصر متفرقة ═══════════ */
#toTop{position:fixed;inset-inline-end:var(--u4);bottom:var(--u4);width:46px;height:46px;border-radius:var(--r2);border:1px solid var(--line);background:var(--card);color:var(--ink);display:inline-flex;align-items:center;justify-content:center;box-shadow:var(--shadow);cursor:pointer;opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s;z-index:35}
#toTop.show{opacity:1;visibility:visible}
#toTop svg{width:20px;height:20px}
.status-msg{margin:var(--u6) 0;padding:var(--u4) var(--u5);border:1px dashed var(--line2);border-radius:var(--r2);background:var(--card);color:var(--muted)}
.status-msg h1{font-size:24px;color:var(--ink)}
.no-posts{padding:var(--u8) var(--u5);text-align:center;color:var(--muted)}
.widget-title-hidden{display:none}

/* ═══════════ ⑩ الطباعة ═══════════ */
@media print{
  .site-header,.sidebar,.site-footer,.share,.comments,#toTop,.pager{display:none!important}
  body{background:#fff;color:#000;font-size:12pt}
  .post{border:0;box-shadow:none;padding:0}
  .post-body a{color:#000;border:0;text-decoration:underline}
}

/* ═══════════ ⑪ أنماط أدوات بلوجر الافتراضية (تكملة) ═══════════ */
/* تبديل أيقونة الوضع الليلي */
.ic-sun{display:none}
html[data-theme="dark"] .ic-sun{display:block}
html[data-theme="dark"] .ic-moon{display:none}
/* أدوات بلا إطار داخل الهيدر والفوتر وبطاقاتها */
.brand-sec .widget,.brand-sec .widget .widget-content,.main-menu .widget,.main-menu .widget .widget-content,
.hdr-pages .widget,.hdr-pages .widget .widget-content,.hdr-social .widget,.hdr-social .widget .widget-content,
.foot-social-sec .widget,.foot-social-sec .widget .widget-content,.foot-attr .widget,.foot-attr .widget .widget-content{
  background:none;border:0;box-shadow:none;padding:0;margin:0
}
.widget .title:empty,.widget h2.title:empty{display:none}
.brand #header-inner{background:none!important;padding:0!important}
/* شريط الصفحات العلوي */
.hdr-pages ul,.hdr-social ul{display:flex;align-items:center;gap:var(--u1);list-style:none;margin:0;padding:0;flex-wrap:wrap}
.hdr-pages li,.hdr-social li{margin:0}
.hdr-pages a{display:inline-flex;align-items:center;height:30px;padding:0 var(--u3);border-radius:8px;font-size:13.5px;font-weight:600;color:var(--muted)}
.hdr-pages a:hover{background:var(--soft);color:var(--ink);text-decoration:none}
.hdr-social{margin-inline-start:auto}
.hdr-social a{display:inline-flex;align-items:center;height:30px;padding:0 var(--u2);border-radius:8px;font-size:13px;color:var(--muted)}
.hdr-social a:hover{background:var(--soft);color:var(--ink);text-decoration:none}
/* القائمة الرئيسية */
.main-menu ul{display:flex;align-items:center;gap:var(--u1);list-style:none;margin:0;padding:0;flex-wrap:wrap}
.main-menu li{margin:0}
@media (max-width:980px){
  .main-menu ul{flex-direction:column;align-items:stretch}
  .main-menu a{display:flex;height:48px;align-items:center;padding:0 var(--u3);border-radius:var(--r2);font-weight:600;color:var(--ink)}
  .main-menu a:hover{background:var(--soft);text-decoration:none;color:var(--brand)}
}
/* القائمة الجانبية والفوتر */
.side-sec{display:grid;gap:var(--u5)}
@media (max-width:980px){.main-col{min-width:0}.hdr-actions{margin-inline-start:auto}}
.foot-sec{display:grid;gap:var(--u4);align-content:start}
.foot-social-sec ul{display:flex;gap:var(--u2);list-style:none;margin:0;padding:0;flex-wrap:wrap}
.foot-social-sec a{display:inline-flex;align-items:center;padding:6px var(--u3);border:1px solid var(--line);border-radius:999px;font-size:13.5px;color:var(--muted);background:var(--soft)}
.foot-social-sec a:hover{background:var(--brand);border-color:var(--brand);color:#fff;text-decoration:none}
.attribution ul{display:flex;gap:var(--u3);list-style:none;margin:0;padding:0;flex-wrap:wrap}
.attribution .widget-content{display:flex;gap:var(--u3);align-items:center;flex-wrap:wrap}
/* التعليقات */
.comment-list{list-style:none;margin:0;padding:0;display:grid;gap:var(--u3)}
.comment-replies{list-style:none;margin:var(--u2) 0 0;padding-inline-start:var(--u4);border-inline-start:2px solid var(--line);display:grid;gap:var(--u2)}
.comment-form iframe{min-height:340px}
/* متفرقات */
.status-msg a{display:inline-flex;align-items:center;height:44px;padding:0 var(--u5);border-radius:var(--r2);background:var(--brand);color:#fff;font-weight:700}
.status-msg a:hover{text-decoration:none;opacity:.92}
input[type=search]::placeholder{color:var(--muted);opacity:.85}
.post-body details{background:var(--card)}
.widget.LinkList li a{font-weight:600}

body.script:
/**/
/* ══════════════════════════════════════════════════════════════════
   Hub Template — app.js
   كل هذا الكود مكتوب من الصفر: وضع ليلي، قائمة الهاتف، بحث، فهرس
   محتويات تلقائي، أسئلة منسدلة، صور محسّنة، مشاركة، وقت قراءة.
   لا طلبات شبكة خارجية · لا مكتبات · بلا أي أثر على سرعة الصفحة.
   ══════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var d = document, r = d.documentElement;
  function $(s, c) { return (c || d).querySelector(s); }
  function $$(s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); }
  function on(el, ev, fn, opt) { if (el) el.addEventListener(ev, fn, opt || false); }
  function txt(n) { return (n.textContent || '').replace(/\s+/g, ' ').trim(); }

  /* ── ① الوضع الليلي ───────────────────────────────────────────── */
  var KEY = 'ahub-theme';
  function paint(mode) {
    var dark = (mode === 'dark');
    r.setAttribute('data-theme', dark ? 'dark' : 'light');
    if (dark) { r.setAttribute('mode', 'dark'); } else { r.removeAttribute('mode'); }
    var b = $('#ahubTheme');
    if (b) {
      b.setAttribute('aria-pressed', dark ? 'true' : 'false');
      b.setAttribute('title', dark ? 'Light mode' : 'Dark mode');
      b.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode');
    }
    var meta = $('#ahub-theme-color');
    if (meta) {
      var bg = '';
      try { bg = getComputedStyle(r).getPropertyValue('--bg').trim(); } catch (e) {}
      meta.setAttribute('content', bg || (dark ? '#14161F' : '#FBF3E0'));
    }
  }
  function current() { return r.getAttribute('data-theme') === 'dark' ? 'dark' : 'light'; }
  function toggleTheme() {
    var next = current() === 'dark' ? 'light' : 'dark';
    try { localStorage.setItem(KEY, next); } catch (e) {}
    paint(next);
  }
  on($('#ahubTheme'), 'click', toggleTheme);
  paint(current());
  try {
    if (window.matchMedia) {
      var mq = window.matchMedia('(prefers-color-scheme: dark)');
      var h = function (e) { var saved = null; try { saved = localStorage.getItem(KEY); } catch (x) {} if (!saved) paint(e.matches ? 'dark' : 'light'); };
      if (mq.addEventListener) { mq.addEventListener('change', h); } else if (mq.addListener) { mq.addListener(h); }
    }
  } catch (e) {}

  /* ── ② قائمة الهاتف ──────────────────────────────────────────── */
  var nav = $('#main-nav'), navTg = $('#navToggle'), scrim = $('#navScrim'), navClose = $('#navClose');
  function drawer(open) {
    if (!nav) { return; }
    nav.classList.toggle('is-open', !!open);
    if (scrim) { scrim.classList.toggle('is-open', !!open); }
    if (navTg) { navTg.setAttribute('aria-expanded', open ? 'true' : 'false'); }
    if (window.innerWidth <= 980) { r.style.overflow = open ? 'hidden' : ''; }
    if (open) { var f = $('a, button', nav); if (f && f.focus) { f.focus(); } }
  }
  on(navTg, 'click', function () { drawer(!(nav && nav.classList.contains('is-open'))); });
  on(navClose, 'click', function () { drawer(false); });
  on(scrim, 'click', function () { drawer(false); });
  $$('#main-nav a').forEach(function (a) { on(a, 'click', function () { drawer(false); }); });

  /* ── ③ البحث ─────────────────────────────────────────────────── */
  var sForm = $('#hdrSearch'), sTg = $('#searchToggle'), sIn = $('#searchInput');
  on(sTg, 'click', function () {
    if (!sForm) { return; }
    var open = sForm.classList.toggle('open');
    if (sTg) { sTg.setAttribute('aria-expanded', open ? 'true' : 'false'); }
    if (open) { setTimeout(function () { if (sIn) { sIn.focus(); } }, 130); }
    else if (sIn && sIn.value.trim()) { sForm.submit(); }
  });
  on(sIn, 'blur', function () { if (sIn.value.trim() === '' && sForm) { sForm.classList.remove('open'); } });

  /* ── ④ ظل الهيدر + العودة للأعلى ─────────────────────────────── */
  var hdr = $('#site-header'), topBtn = $('#toTop');
  function onScroll() {
    var y = window.pageYOffset || r.scrollTop || 0;
    if (hdr) { hdr.classList.toggle('is-scrolled', y > 8); }
    if (topBtn) { topBtn.classList.toggle('show', y > 700); }
  }
  on(window, 'scroll', onScroll, { passive: true });
  onScroll();
  on(topBtn, 'click', function () {
    var reduce = false;
    try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
    if (reduce) { window.scrollTo(0, 0); } else { window.scrollTo({ top: 0, behavior: 'smooth' }); }
  });
  on(d, 'keydown', function (e) { if (e.key === 'Escape') { drawer(false); if (sForm) { sForm.classList.remove('open'); } } });

  /* ── ⑤ السنة في الفوتر ──────────────────────────────────────── */
  var yr = $('#ahubYear'); if (yr) { yr.textContent = new Date().getFullYear(); }

  /* ── ⑥ المشاركة ─────────────────────────────────────────────── */
  var share = $('#ahubShare');
  if (share) {
    var url = share.getAttribute('data-url') || location.href;
    var title = (d.title || '').split('|')[0].replace(/\s+/g, ' ').trim();
    var ICONS = {
      wa: '<path d="M20 11.9A8 8 0 0 1 8.1 19l-3.6 1 1-3.5A8 8 0 1 1 20 11.9z"/><path d="M9 9.5c0 3 2.5 5.5 5.5 5.5"/>',
      x: '<path d="M4.5 4.5l6.8 8.6-6.6 6.4h2.3l5.4-5.2 4.1 5.2h3.5l-7.1-9L19 4.5h-2.3l-4.9 4.7-3.8-4.7z"/>',
      fb: '<path d="M14.5 8.5h2.3v-3h-2.3c-1.9 0-3.4 1.5-3.4 3.4v1.6H9v3h2.1v6h3v-6h2.3l.4-3h-2.7V9.2c0-.4.3-.7.7-.7z"/>',
      link: '<path d="M9.7 14.3l4.6-4.6"/><path d="M8.5 12.1L7 13.6a3.5 3.5 0 0 0 5 5l1.5-1.5"/><path d="M15.5 11.9l1.5-1.5a3.5 3.5 0 0 0-5-5l-1.5 1.5"/>'
    };
    function btn(tag, cls, href, label, iconPath) {
      var el = d.createElement(tag);
      el.className = cls || '';
      if (href) { el.href = href; el.target = '_blank'; el.rel = 'noopener noreferrer'; }
      el.setAttribute('aria-label', label); el.setAttribute('title', label);
      el.innerHTML = '<svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" viewBox="0 0 24 24" aria-hidden="true">' + iconPath + '</svg>';
      return el;
    }
    share.appendChild(btn('a', '', 'https://wa.me/?text=' + encodeURIComponent(title + ' — ' + url), 'Share on WhatsApp', ICONS.wa));
    share.appendChild(btn('a', '', 'https://twitter.com/intent/tweet?text=' + encodeURIComponent(title) + '&url=' + encodeURIComponent(url), 'Share on X', ICONS.x));
    share.appendChild(btn('a', '', 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url), 'Share on Facebook', ICONS.fb));
    var copy = btn('button', '', '', 'Copy link', ICONS.link);
    copy.type = 'button';
    on(copy, 'click', function () {
      var done = function () { copy.classList.add('copied'); copy.setAttribute('aria-label', 'Link copied'); setTimeout(function () { copy.classList.remove('copied'); copy.setAttribute('aria-label', 'Copy link'); }, 1800); };
      try {
        if (navigator.clipboard) { navigator.clipboard.writeText(url).then(done, function () {}); }
        else {
          var ta = d.createElement('textarea'); ta.value = url; ta.style.position = 'fixed'; ta.style.opacity = '0';
          d.body.appendChild(ta); ta.select(); d.execCommand('copy'); d.body.removeChild(ta); done();
        }
      } catch (e) {}
    });
    share.appendChild(copy);
  }

  /* ── ⑦ تحسينات المقال ───────────────────────────────────────── */
  var body = $('#ahub-body');
  if (body) {
    var reduce = false;
    try { reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

    /* 7.1 جدول المحتويات التلقائي */
    try {
      var hs = $$('h2', body), items = [], i, h, t;
      for (i = 0; i < hs.length; i++) {
        h = hs[i]; t = txt(h);
        if (!t) { continue; }
        if (/^(frequently asked questions|sources and further reading|keep reading|related guides)$/i.test(t)) { continue; }
        if (!h.id) { h.id = 'ahub-toc-' + i; }
        items.push([h.id, t.replace(/^\d+[\.\)]?\s*/, '')]);
      }
      if (items.length >= 3) {
        var box = d.createElement('div'); box.className = 'toc'; box.setAttribute('role', 'navigation'); box.setAttribute('aria-label', 'Table of contents');
        var head = d.createElement('button'); head.type = 'button'; head.className = 'toc-head';
        head.setAttribute('aria-expanded', 'false'); head.setAttribute('aria-controls', 'ahub-toc-list');
        head.innerHTML = '<span>Table of contents</span><span class="hint">show</span>';
        var ol = d.createElement('ol'); ol.id = 'ahub-toc-list'; ol.hidden = true;
        for (i = 0; i < items.length; i++) {
          var li = d.createElement('li'), a = d.createElement('a');
          a.href = '#' + items[i][0]; a.textContent = items[i][1]; li.appendChild(a); ol.appendChild(li);
        }
        box.appendChild(head); box.appendChild(ol);
        var anchor = $('.ahub-key', body) || body.firstElementChild;
        if (anchor && anchor.parentNode) { anchor.parentNode.insertBefore(box, anchor.nextSibling); }
        on(head, 'click', function () {
          var open = ol.hidden;
          ol.hidden = !open;
          head.setAttribute('aria-expanded', open ? 'true' : 'false');
          var hint = $('.hint', head); if (hint) { hint.textContent = open ? 'hide' : 'show'; }
        });
        $$('a', ol).forEach(function (a) {
          on(a, 'click', function (e) {
            var target = d.getElementById(a.getAttribute('href').slice(1));
            if (!target) { return; }
            e.preventDefault();
            var y = target.getBoundingClientRect().top + (window.pageYOffset || r.scrollTop || 0) - 96;
            if (reduce) { window.scrollTo(0, y); } else { window.scrollTo({ top: y, behavior: 'smooth' }); }
            try { history.replaceState(null, '', a.getAttribute('href')); } catch (x) {}
          });
        });
      }
    } catch (e) {}

    /* 7.2 بطاقة «الإجابة السريعة» من فقرة تبدأ بـ Quick answer: */
    try {
      var ps = $$('p', body), k;
      for (k = 0; k < ps.length; k++) {
        if (/^quick answer\s*:/i.test(txt(ps[k]))) {
          var card = d.createElement('div'); card.className = 'ahub-key';
          var lab = d.createElement('span'); lab.className = 'ahub-key-label'; lab.textContent = 'QUICK ANSWER';
          var fc = ps[k].firstChild;
          if (fc && fc.nodeType === 3) { fc.nodeValue = fc.nodeValue.replace(/^\s*quick answer\s*:\s*/i, ''); }
          ps[k].parentNode.insertBefore(card, ps[k]);
          card.appendChild(lab); card.appendChild(ps[k]);
          break;
        }
      }
    } catch (e) {}

    /* 7.3 الأسئلة الشائعة → منسدلات تلقائيًا */
    try {
      var h2s = $$('h2', body), m;
      for (m = 0; m < h2s.length; m++) {
        if (/frequently asked questions/i.test(txt(h2s[m]))) {
          var start = h2s[m].nextElementSibling, wrap = d.createElement('div'); wrap.className = 'ahub-faq';
          var node = start, made = 0;
          while (node && node.tagName !== 'H2') {
            var next = node.nextElementSibling;
            if (node.tagName === 'H3') {
              var det = d.createElement('details'); if (made === 0) { det.open = true; }
              var sum = d.createElement('summary'); sum.textContent = txt(node);
              var ans = d.createElement('div'); ans.className = 'ahub-a';
              var sib = next;
              while (sib && sib.tagName !== 'H3' && sib.tagName !== 'H2') { var after = sib.nextElementSibling; ans.appendChild(sib); sib = after; }
              det.appendChild(sum); det.appendChild(ans); wrap.appendChild(det); made++;
              node = sib; continue;
            }
            node = next;
          }
          if (made) { h2s[m].parentNode.insertBefore(wrap, h2s[m].nextSibling); }
          break;
        }
      }
    } catch (e) {}

    /* 7.4 الجداول: حاوية قابلة للتمرير */
    try {
      $$('table', body).forEach(function (tb) {
        if (tb.parentNode && tb.parentNode.className === 'tbl-wrap') { return; }
        var w = d.createElement('div'); w.className = 'tbl-wrap';
        tb.parentNode.insertBefore(w, tb); w.appendChild(tb);
      });
    } catch (e) {}

    /* 7.5 الصور: تحميل مؤجل + وصف تلقائي + أولوية للصورة الأولى */
    try {
      var imgs = $$('img', body), alt = (d.title || 'AI Hub').split('|')[0].trim(), n;
      for (n = 0; n < imgs.length; n++) {
        var im = imgs[n];
        if (n === 0) { im.setAttribute('fetchpriority', 'high'); }
        else {
          if (!im.getAttribute('loading')) { im.setAttribute('loading', 'lazy'); }
          if (!im.getAttribute('decoding')) { im.setAttribute('decoding', 'async'); }
        }
        if (!im.getAttribute('alt')) { im.setAttribute('alt', alt); }
      }
    } catch (e) {}

    /* 7.6 الروابط الخارجية: نافذة جديدة + rel آمن */
    try {
      $$('a', body).forEach(function (a) {
        var href = a.getAttribute('href') || '';
        if (href.indexOf('http') !== 0) { return; }
        if (a.host === location.host) { return; }
        a.setAttribute('target', '_blank');
        a.setAttribute('rel', 'noopener noreferrer');
      });
    } catch (e) {}

    /* 7.7 وقت القراءة */
    try {
      var words = (body.textContent || '').replace(/\s+/g, ' ').trim().split(' ').length;
      var mins = Math.max(2, Math.round(words / 220));
      var rt = $('.ahub-rt');
      if (rt) { rt.textContent = '· ' + mins + ' min read'; }
    } catch (e) {}
  }
})();
/**/
